import pandas as pd
import requests
from io import StringIO


def task_func(csv_url_dict, sort_by_column="title"):
    if not csv_url_dict or "URL" not in csv_url_dict:
        raise ValueError('The dictionary is empty or does not contain the key "URL".')

    response = requests.get(csv_url_dict["URL"])
    response.raise_for_status()

    df = pd.read_csv(StringIO(response.text))
    return df.sort_values(by=sort_by_column)
